var EXTRA=[{dot:"gray",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Un indice di accoppiamento slope-menisco per il rientro dopo LCA",v:"Proposto come marcatore per escludere il rischio, non ancora per decidere in sala operatoria; abstract non disponibile su PubMed.",pmid:'42748367',doi:'10.1002/ksa.70580',temi:["slope tibiale","menisco","LCA"]},{dot:"gray",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Prospettive multidisciplinari sull'augmentazione biologica nella sutura meniscale",v:"Integra chirurgia, radiologia e riabilitazione; abstract non disponibile su PubMed, natura dell'articolo non specificata.",pmid:'42748352',doi:'10.1002/ksa.70609',temi:["menisco","augmentazione biologica","riabilitazione"]},{dot:"gray",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Ridefinire il «fallimento soggettivo» dopo ricostruzione del crociato posteriore",v:"Rilegge il punteggio KOOS-qualità di vita come criterio di fallimento soggettivo; abstract non disponibile su PubMed.",pmid:'42748371',doi:'10.1002/ksa.70610',temi:["LCP","esiti riferiti dal paziente","revisione"]},{dot:"gray",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Come si rompe il crociato nella pallamano, dal registro danese",v:"Quasi cinquemila infortuni analizzati: soprattutto senza contatto, in possesso di palla, durante finte o tiri.",pmid:'42748360',doi:'10.1002/ksa.70595',temi:["LCA","pallamano","meccanismo di infortunio"]},{dot:"gray",j:"Ochsner Journal",h:"L'ADHD non peggiora gli esiti dopo ricostruzione del crociato nei giovani",v:"Database nazionale USA: né la diagnosi né la terapia farmacologica per ADHD si associano a esiti peggiori dopo LCA.",pmid:'42746451',doi:'10.31486/toj.26.0021',temi:["LCA","comorbidità psichiatriche","esiti"]},{dot:"gray",j:"Arthroscopy",h:"Il plasma ricco di piastrine batte l'acido ialuronico, ma il prodotto conta",v:"Editoriale di commento: il vantaggio clinico dipende dalla formulazione del PRP, non dall'acronimo — standardizzazione ancora mancante.",pmid:'42747127',doi:'10.1002/arj.70588',temi:["PRP","artrosi","orthobiologics"]},{dot:"gray",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Guida aggiornata su anatomia ed esame clinico del collaterale mediale",v:"Current concepts a firma corale — D'Ambrosi, Musahl, Getgood, Williams fra gli autori — su anatomia, biomeccanica ed esame dell'MCL; nessun dato clinico nuovo.",pmid:'42748362',doi:'10.1002/ksa.70588',temi:["collaterale mediale","anatomia","esame clinico"]},{dot:"gray",j:"Journal of Experimental Orthopaedics",h:"L'estrusione del menisco durante il cammino segnala l'artrosi precoce",v:"Uno studio giapponese misura l'estrusione meniscale in movimento, non solo da fermi, per individuare il sovraccarico del compartimento mediale.",pmid:'42746394',doi:'10.1002/jeo2.70910',temi:["estrusione meniscale","artrosi precoce","biomeccanica del cammino"]},{dot:"gray",j:"Tzu Chi Medical Journal",h:"Come gestire il femore molto arcuato nella protesi di ginocchio",v:"Revisione sistematica su tecniche di correzione dell'allineamento nei pazienti, soprattutto asiatici, con marcato arco femorale.",pmid:'42746619',doi:'10.4103/tcmj.TCMJ-D-25-00069',temi:["protesi totale","deformità femorale","allineamento"]},{dot:"gray",j:"Advances in Radiation Oncology",h:"La radioterapia preoperatoria nella revisione per artrofibrosi del ginocchio",v:"Serie piccola a un centro: miglior arco di movimento dopo revisione con radioterapia a bassa dose prima dell'intervento.",pmid:'42746543',doi:'10.1016/j.adro.2026.102110',temi:["artrofibrosi","revisione protesica","radioterapia"]},{dot:"gray",j:"International Orthopaedics",h:"Il peso corporeo prima della protesi pesa sul recupero delle attività quotidiane",v:"Coorte giapponese: più alto l'indice di massa corporea, più frequente il calo delle attività quotidiane dopo l'intervento.",pmid:'42747570',doi:'10.1007/s00264-026-07036-2',temi:["protesi totale","obesità","attività quotidiane"]},{dot:"gray",j:"Orthopaedic Surgery",h:"La proteina C reattiva sale di più al secondo ginocchio operato in una settimana",v:"Nella protesi bilaterale in due tempi ravvicinati, il secondo intervento porta un carico infiammatorio più alto — non un segnale d'infezione da solo.",pmid:'42749480',doi:'10.1111/os.70434',temi:["protesi bilaterale","infiammazione post-operatoria","infezione"]},{dot:"gray",j:"Scandinavian Journal of Medicine & Science in Sports",h:"La bicicletta carica meno il ginocchio della corsa, anche con artrosi",v:"Analisi biomeccanica: pedalare non supera il carico della camminata, mentre la corsa lo supera nettamente, soprattutto sul piano frontale nell'artrosi.",pmid:'42746972',doi:'10.1111/sms.70369',temi:["artrosi","biomeccanica","attività fisica"]}];
var SCOPERTE=[{t:"Una protesi di ginocchio con pompe magnetiche integrate",v:"Un prototipo di ricerca inserisce micro-pompe magnetiche in una protesi per campionare liquido articolare e rilasciare farmaco su richiesta, monitorando la salute dell'impianto dall'interno. Ancora lontano dalla pratica clinica, ma indica dove sta andando l'ingegneria degli impianti.",pmid:'42746481',doi:'10.1016/j.device.2026.101203',temi:["bioingegneria","impianti intelligenti","protesi"]},{t:"Una rete neurale scopre l'osteoporosi guardando una radiografia del ginocchio",v:"Un modello di intelligenza artificiale addestrato su 580 radiografie di ginocchio raggiunge un'accuratezza diagnostica onesta (AUC 0,87) nello screening opportunistico dell'osteoporosi, proposto come aiuto a decidere chi inviare a un esame dedicato, non come sostituto della densitometria.",pmid:'42736491',doi:'10.1007/s10278-026-02276-5',temi:["intelligenza artificiale","osteoporosi","imaging"]},{t:"Un percorso clinico cinese per la protesi di ginocchio ad alta conformità",v:"Un consenso di esperti cinesi propone un percorso clinico strutturato per la protesi di ginocchio personalizzata ad alta conformità con approccio mininvasivo — uno sguardo su come si sta organizzando la personalizzazione implantare nel sistema sanitario cinese.",pmid:'42749319',doi:'10.7507/1002-1892.202607056',temi:["mondo orientale","protesi personalizzata","percorso clinico"]}];
var SOC={"1": {"video": "Centosei esperti internazionali — il gruppo europeo ESSKA insieme a EKA, EHS e APAS — hanno messo insieme un consenso formale su come organizzare al meglio il percorso di recupero rapido dopo protesi di anca e di ginocchio, dal periodo preoperatorio fino alla dimissione dall'ospedale. È un lavoro fatto con un metodo rigoroso: un gruppo di esperti ha proposto le domande, un secondo gruppo indipendente le ha votate, un terzo ne ha controllato l'applicabilità in paesi e sistemi sanitari diversi. Il risultato sono 63 raccomandazioni pratiche. La maggior parte è basata su evidenza scientifica solida, e anche le raccomandazioni che restano opinione di esperti hanno ricevuto un accordo molto alto fra tutti i partecipanti. Coprono davvero tutto il percorso: come prepararsi prima dell'intervento, cosa succede in sala operatoria, come gestire il dolore e la mobilizzazione nei primi giorni, quando è sicuro tornare a casa. Non riguarda la tecnica chirurgica in sé, cioè come viene eseguita l'operazione, ma tutto ciò che la circonda. È un riferimento utile per il medico curante, per il fisioterapista e per il paziente stesso, per capire che cosa aspettarsi da un percorso di recupero ben organizzato dopo un intervento di protesi — e per riconoscere quando un percorso segue davvero le pratiche migliori oggi disponibili."}, "2": {"video": "Un centro italiano di riferimento per la chirurgia del ginocchio ha seguito 168 protesi parziali di ginocchio per fino a quindici anni: la sopravvivenza resta molto alta lungo tutto il periodo, dal cento per cento a cinque anni fino al settantotto per cento a quindici anni, un risultato che conferma la solidità di questo tipo di intervento nel tempo. Le malattie associate del paziente, prese singolarmente — pressione alta, diabete, problemi cardiaci — da sole non sembrano influenzare il rischio di dover rioperare, anche in pazienti con più di una condizione insieme. Chi aveva già subito un intervento sullo stesso ginocchio in passato, invece, mostra un punteggio funzionale più basso — un segnale da tenere d'occhio, anche se non ancora una certezza statistica piena. Il messaggio pratico per chi deve operarsi: la protesi parziale di ginocchio tiene molto bene nel tempo, ed è una scelta solida quando indicata. La storia chirurgica pregressa di quel ginocchio merita comunque di essere discussa apertamente prima dell'intervento con il proprio chirurgo, anche se la scienza non ha ancora l'ultima parola definitiva su quanto conti davvero."}, "3": {"video": "Uno studio francese, condotto a Marsiglia su oltre trecento pazienti operati di legamento crociato anteriore, mostra che un ginocchio con più pendenza naturale della tibia — una caratteristica anatomica individuale, non una scelta chirurgica — tende, nel tempo, a mantenere un po' più di lassità residua rispetto al ginocchio sano non operato. L'effetto cresce lentamente nei primi due anni dopo l'intervento, mano a mano che il ginocchio riprende le sue normali attività quotidiane e sportive. Aggiungere un rinforzo laterale al lato del ginocchio durante lo stesso intervento sembra ridurre questo effetto nel tempo: chi lo aveva ricevuto mostrava, al controllo di due anni, una lassità residua misurabile più bassa rispetto a chi non lo aveva ricevuto. È uno studio condotto su un solo tipo di innesto, non su tutti quelli oggi in uso nei diversi centri chirurgici: un tassello in più nella conoscenza, non una risposta definitiva, sul valore reale del rinforzo laterale nella ricostruzione del legamento crociato anteriore, soprattutto quando l'innesto scelto è diverso da quello studiato qui."}, "4": {"video": "Uno studio americano condotto su oltre duecentottanta pazienti guarda a una tecnica alternativa rispetto alla ricostruzione classica del legamento crociato: la sutura diretta del legamento lesionato, invece di sostituirlo con un nuovo tendine prelevato altrove nel ginocchio, quando le caratteristiche della lesione lo permettono davvero. A due-cinque anni dall'intervento, circa un paziente su dieci ha avuto un fallimento della riparazione, cioè il legamento non ha tenuto nel tempo. Il rischio risulta più alto quando la guaina naturale che avvolge il legamento è più danneggiata al momento dell'intervento, e nei pazienti più giovani rispetto a quelli di età più avanzata. È una tecnica selettiva, riservata a lesioni con caratteristiche anatomiche molto precise, eseguita solo in centri specializzati con grande esperienza specifica: non sostituisce la ricostruzione standard nella maggior parte dei casi, ma questo studio aiuta a capire meglio per quali pazienti questa alternativa potrebbe non essere la scelta più solida."}, "5": {"video": "Uno studio olandese condotto su venti pazienti operati di correzione dell'asse della gamba mostra che il modo in cui si misura la deformità sulla radiografia — partendo dal centro del ginocchio oppure da un punto più spostato verso l'esterno — può cambiare in modo sostanziale il risultato della misura stessa, anche sulla stessa identica immagine radiografica. In circa un caso su tre, il tipo di deformità attribuito al femore cambia completamente a seconda di quale dei due metodi di misura viene utilizzato dal chirurgo durante la fase di pianificazione preoperatoria dell'intervento correttivo. È uno studio piccolo e limitato solo alla fase di misura, non ancora collegato ai risultati clinici reali dei pazienti operati: resta comunque un invito concreto a discutere con il proprio chirurgo quale metodo di pianificazione radiografica utilizza abitualmente prima di un intervento di correzione dell'asse della gamba."}, "6": {"video": "Uno studio condotto su novanta ginocchia di ragazzi, in tre centri diversi fra Basilea e Stanford, mostra una possibile connessione anatomica fra la posizione di uno dei due fasci del legamento crociato anteriore e una lesione della cartilagine chiamata osteocondrite dissecante, che colpisce soprattutto i più giovani durante la crescita. Nei ragazzi con questa lesione localizzata sul lato esterno del ginocchio, uno dei due fasci del legamento crociato anteriore, quello postero-laterale, si inserisce in un punto anatomico diverso rispetto a chi non ha questa stessa lesione, sia nel gruppo di controllo sano sia nel gruppo con la lesione sul lato opposto. È uno studio di anatomia descrittiva, non su un intervento chirurgico specifico: aiuta soprattutto a capire meglio una condizione della cartilagine che colpisce bambini e adolescenti in fase di crescita, più che a cambiare qualcosa nella pratica quotidiana di un chirurgo che opera prevalentemente pazienti adulti."}};
var SOCV={"1": {"video": {"chir": ["Un consenso formale internazionale — 106 esperti, il gruppo ESSKA insieme a EKA, EHS e APAS — ha appena pubblicato 63 raccomandazioni condivise sui percorsi fast-track ed ERAS per la protesi di anca e di ginocchio. Il metodo è quello di un vero consenso formale: un gruppo direttivo di 22 esperti ha scritto 37 domande, un gruppo di valutazione indipendente di 35 esperti le ha votate su scala 1-9 in due round, e un gruppo di revisione paritaria di 49 esperti ne ha verificato l'applicabilità in contesti diversi.", "Trentanove delle 63 raccomandazioni sono gradate A o B, cioè basate su evidenza di livello alto; le altre ventiquattro restano opinione di esperti, ma con un accordo medio molto alto, fra 7,7 e 8,9 su una scala a nove punti. Cinquantasei raccomandazioni su sessantatré sono state giudicate appropriate con forte accordo, solo sette con accordo relativo — un livello di convergenza raro per un documento internazionale su un tema perioperatorio così ampio, che copre preoperatorio, sala operatoria e dimissione.", "Non è un documento su una tecnica chirurgica: è una cornice condivisa per tutto ciò che circonda l'intervento — gestione del dolore, mobilizzazione precoce, criteri di dimissione sicura. Per chi opera protesi di ginocchio ogni settimana, come nel tuo caso con il sistema VELYS, è un metro di paragone nuovo per il proprio protocollo perioperatorio, non un'indicazione da applicare meccanicamente senza guardare il singolo paziente davanti a te."], "misto": ["Centosei esperti internazionali — il gruppo europeo ESSKA insieme a EKA, EHS e APAS — hanno messo insieme un consenso formale su come organizzare al meglio il percorso di recupero rapido dopo protesi di anca e di ginocchio, dal periodo preoperatorio fino alla dimissione dall'ospedale. È un lavoro fatto con un metodo rigoroso: un gruppo di esperti ha proposto le domande, un secondo gruppo indipendente le ha votate, un terzo ne ha controllato l'applicabilità in paesi e sistemi sanitari diversi.", "Il risultato sono 63 raccomandazioni pratiche. La maggior parte è basata su evidenza scientifica solida, e anche le raccomandazioni che restano opinione di esperti hanno ricevuto un accordo molto alto fra tutti i partecipanti. Coprono davvero tutto il percorso: come prepararsi prima dell'intervento, cosa succede in sala operatoria, come gestire il dolore e la mobilizzazione nei primi giorni, quando è sicuro tornare a casa.", "Non riguarda la tecnica chirurgica in sé, cioè come viene eseguita l'operazione, ma tutto ciò che la circonda. È un riferimento utile per il medico curante, per il fisioterapista e per il paziente stesso, per capire che cosa aspettarsi da un percorso di recupero ben organizzato dopo un intervento di protesi — e per riconoscere quando un percorso segue davvero le pratiche migliori oggi disponibili."], "pazienti": ["Un gruppo di 106 specialisti da tutto il mondo ha messo per iscritto, insieme, le regole per organizzare al meglio il periodo attorno a un intervento di protesi d'anca o di ginocchio. Non un solo medico, ma un gruppo molto ampio che si è confrontato per mesi, votando ogni singola raccomandazione più volte prima di considerarla definitiva.", "Il risultato sono 63 indicazioni pratiche su come prepararsi prima dell'intervento, che cosa succede davvero in sala operatoria, e come vengono gestiti i primi giorni dopo — dal controllo del dolore alla ripresa del movimento — tutto pensato per farti tornare a muoverti prima e in sicurezza, senza correre rischi inutili.", "Questo non cambia il modo in cui si opera: cambia come viene organizzato tutto il percorso attorno all'intervento, dal giorno prima della protesi fino al ritorno a casa. Se stai per operarti, è un buon motivo per chiedere al tuo chirurgo come è strutturato il tuo percorso di recupero, e se segue indicazioni di questo tipo."]}, "reel": {"chir": ["[106 esperti · 63 raccomandazioni] Consenso ESSKA/EKA-EHS-APAS sul fast-track in protesi d'anca e ginocchio.", "39/63 raccomandazioni di grado A-B, accordo 7,7-8,9/9. Copre pre-, intra- e postoperatorio.", "[Non una tecnica, un percorso] Un nuovo metro di paragone per il tuo protocollo perioperatorio."], "misto": ["[Consenso internazionale] 106 esperti su come organizzare il recupero rapido dopo protesi d'anca e ginocchio.", "63 raccomandazioni pratiche, per lo più basate su evidenza solida, con accordo molto alto.", "[Il percorso, non la tecnica] Dolore, mobilizzazione, dimissione — un riferimento per tutto il team di cura."], "pazienti": ["[Come si organizza un buon recupero] 106 specialisti nel mondo si sono messi d'accordo.", "63 indicazioni su preparazione, intervento e primi giorni dopo, per tornare a muoverti prima.", "[Parlane col tuo chirurgo] Non cambia l'operazione, cambia il percorso attorno ad essa."]}, "linkedin": {"chir": ["Consenso formale ESSKA/EKA, EHS e APAS su fast-track/ERAS in artroplastica di anca e ginocchio: 106 esperti (steering 22, rating 35, peer review 49), 37 domande, 63 raccomandazioni finali.", "39/63 raccomandazioni gradate A o B (evidenza di livello alto), 24 C o D (opinione di esperti). Accordo medio 7,7-8,9/9. 56 giudicate appropriate con forte accordo, 7 con accordo relativo. Copertura completa del percorso: preoperatorio, intraoperatorio, postoperatorio.", "Limiti: 24 raccomandazioni su 63 restano opinione non graduata su evidenza alta; nessuna specifica per singola piattaforma robotica. Resta il primo quadro internazionale formalmente concordato sul fast-track in artroplastica di ginocchio: un riferimento per confrontare il proprio protocollo perioperatorio, non per sostituirlo automaticamente."], "misto": ["Un consenso internazionale di 106 esperti (ESSKA/EKA, EHS, APAS) ha messo per iscritto 63 raccomandazioni su come organizzare il percorso di recupero rapido dopo protesi di anca e ginocchio.", "Trentanove delle 63 sono basate su evidenza solida, le altre su opinione di esperti con accordo comunque molto alto. Coprono tutto il percorso: prima, durante e dopo l'intervento.", "Un limite onesto: parte delle raccomandazioni resta opinione esperta, non dimostrazione. Ma è la prima cornice concordata a questo livello su un tema che riguarda ogni paziente operato di protesi."], "pazienti": ["Centosei specialisti da tutto il mondo hanno definito insieme le buone pratiche per il periodo attorno a un intervento di protesi d'anca o di ginocchio.", "Sessantatré indicazioni pratiche su preparazione, intervento e primi giorni dopo, pensate per un recupero più rapido e sicuro.", "Non riguardano la tecnica dell'operazione, ma tutto quello che la circonda — un buon motivo per parlarne apertamente con il proprio chirurgo prima di operarsi."]}, "instagram": {"chir": ["🌍 106 esperti, un consenso solo: le prime regole condivise sul fast-track in protesi d'anca e ginocchio (ESSKA/EKA, EHS, APAS).", "63 raccomandazioni, 39 su evidenza forte. Preoperatorio, sala operatoria, dimissione: tutto il percorso, non solo il taglio chirurgico.", "Non sostituisce il giudizio clinico — ma dà per la prima volta un metro comune internazionale."], "misto": ["🌍 Un consenso di 106 esperti nel mondo dice come organizzare al meglio il periodo attorno a una protesi di ginocchio o anca.", "63 indicazioni pratiche, dalla preparazione alla dimissione, pensate per un recupero più veloce e sicuro.", "Il messaggio: il percorso attorno all'intervento conta quanto l'intervento stesso."], "pazienti": ["🌍 106 specialisti nel mondo si sono messi d'accordo su come far andare meglio il periodo attorno a una protesi.", "Consigli pratici su come prepararsi, cosa aspettarsi in sala operatoria e come gestire i primi giorni dopo.", "Parlane con il tuo chirurgo: un buon percorso organizzato aiuta quanto un intervento fatto bene."]}}, "2": {"video": {"chir": ["Il Rizzoli di Bologna pubblica la sopravvivenza a lungo termine di 168 protesi monocompartimentali mediali: 100% a 5 anni, 96% a 7, 86% a 10, fino al 78% a 15 anni. Sono numeri da centro ad alto volume, con un follow-up medio di quasi dieci anni sull'intera coorte, e diciotto revisioni osservate in totale su tutto il periodo di osservazione.", "Nella sotto-coorte valutata clinicamente, su 76 ginocchia, la comorbidità da sola non predice la revisione, nemmeno quando più del novanta per cento dei pazienti aveva almeno una malattia associata. Un segnale diverso, che però non raggiunge la significatività statistica: chi aveva già subito un intervento sullo stesso ginocchio in passato ha un punteggio clinico Knee Society più basso, e una tendenza — non dimostrata con certezza — a più complicanze o revisioni, ventotto per cento contro otto.", "Sono numeri che confermano la solidità della monocompartimentale nel tempo, da un centro della tua stessa rete di riferimento — Zaffagnini, Grassi, Marcheggiani Muccioli — e insieme un promemoria per il colloquio preoperatorio: la storia chirurgica pregressa di quel ginocchio conta, anche se questo singolo studio da solo non basta a dimostrarlo con la certezza statistica che vorremmo."], "misto": ["Un centro italiano di riferimento per la chirurgia del ginocchio ha seguito 168 protesi parziali di ginocchio per fino a quindici anni: la sopravvivenza resta molto alta lungo tutto il periodo, dal cento per cento a cinque anni fino al settantotto per cento a quindici anni, un risultato che conferma la solidità di questo tipo di intervento nel tempo.", "Le malattie associate del paziente, prese singolarmente — pressione alta, diabete, problemi cardiaci — da sole non sembrano influenzare il rischio di dover rioperare, anche in pazienti con più di una condizione insieme. Chi aveva già subito un intervento sullo stesso ginocchio in passato, invece, mostra un punteggio funzionale più basso — un segnale da tenere d'occhio, anche se non ancora una certezza statistica piena.", "Il messaggio pratico per chi deve operarsi: la protesi parziale di ginocchio tiene molto bene nel tempo, ed è una scelta solida quando indicata. La storia chirurgica pregressa di quel ginocchio merita comunque di essere discussa apertamente prima dell'intervento con il proprio chirurgo, anche se la scienza non ha ancora l'ultima parola definitiva su quanto conti davvero."], "pazienti": ["Uno studio italiano ha seguito per fino a quindici anni 168 persone operate di protesi parziale di ginocchio — quella che sostituisce solo la parte interna del ginocchio, quella più danneggiata dall'artrosi, lasciando intatto il resto dell'articolazione naturale.", "I risultati sono molto buoni: la grande maggioranza degli impianti funziona ancora bene dopo dieci e persino quindici anni dall'operazione. Avere altre malattie, come la pressione alta o il diabete, non sembra cambiare questo buon risultato nel tempo, anche in chi ne ha più di una insieme.", "Un dato da conoscere, ma non da temere: chi aveva già subito un intervento sullo stesso ginocchio in passato ha mostrato risultati leggermente meno buoni in questo studio. È un motivo in più per raccontare al chirurgo, prima di operarti, ogni intervento fatto in precedenza su quel ginocchio — non un segnale d'allarme per chi deve operarsi oggi."]}, "reel": {"chir": ["[168 UKA · fino a 15 anni] Rizzoli: sopravvivenza 100%→96%→86%→78% a 5-7-10-15 anni.", "Comorbidità: nessuna associazione con la revisione. Chirurgia pregressa: KSS più basso, trend a più complicanze (p=0,054, non significativo).", "[Nel colloquio preoperatorio] La storia chirurgica del ginocchio conta, anche prima che uno studio lo dimostri del tutto."], "misto": ["[Bologna, fino a 15 anni] 168 protesi parziali di ginocchio seguite nel tempo: sopravvivenza alta e stabile.", "Le malattie associate non sembrano cambiare il rischio. Chi aveva già operato quel ginocchio mostra un segnale da approfondire.", "[Il messaggio] La protesi parziale tiene bene; la storia chirurgica pregressa merita spazio nel colloquio."], "pazienti": ["[15 anni di follow-up] Protesi parziale di ginocchio: risultati molto buoni nel tempo, studio italiano su 168 pazienti.", "Avere altre malattie non sembra peggiorare l'esito. Chi aveva già subito un intervento su quel ginocchio ha avuto risultati un po' meno buoni.", "[Parlane col chirurgo] Non è un allarme, è un motivo in più per un colloquio preoperatorio completo."]}, "linkedin": {"chir": ["Cerasoli, Grassi, Zaffagnini, Marcheggiani Muccioli (Istituto Ortopedico Rizzoli): sopravvivenza a lungo termine di 168 UKA mediali, follow-up medio 119,7±29,3 mesi. Kaplan-Meier: 100% a 5 anni, 96% a 7, 86% a 10, 78% a 15.", "Sotto-coorte clinica di 76 ginocchia: 92,1% con almeno una comorbidità, nessuna categoria associata a revisione o esito a lungo termine. Chirurgia ipsilaterale pregressa: KSS più basso (73,6±14,1 contro 80,7±12,5; p=0,036) e trend a più complicanze/revisione (28,6% contro 8,1%; OR 4,56; p=0,054, non significativo).", "Limiti: monocentrico, sotto-coorte clinica piccola, marca dell'impianto non specificata. Conferma robusta della sopravvivenza a lungo termine dell'UKA mediale da un centro ad alto volume; il segnale sulla chirurgia pregressa, seppur non significativo, richiama da un angolo diverso il registro svizzero SIRIS del 15 settembre sul rischio dopo intervento omolaterale precedente."], "misto": ["Uno studio del Rizzoli di Bologna segue 168 protesi parziali di ginocchio fino a quindici anni: la sopravvivenza resta alta a ogni intervallo di tempo controllato.", "Le malattie associate del paziente, prese singolarmente, non sembrano cambiare il rischio di revisione. La chirurgia pregressa sullo stesso ginocchio, invece, si associa a un punteggio clinico più basso — un segnale non ancora statisticamente certo, ma coerente con altri dati recenti su interventi precedenti sullo stesso ginocchio.", "Un promemoria pratico più che una scoperta isolata: la storia chirurgica del ginocchio operato merita spazio nel colloquio preoperatorio, anche quando la statistica non ha ancora l'ultima parola."], "pazienti": ["Uno studio italiano ha seguito 168 persone operate di protesi parziale di ginocchio per fino a quindici anni, con risultati molto solidi nel tempo.", "Avere altre malattie non sembra da solo peggiorare l'esito dell'intervento. Chi aveva già subito un'operazione sullo stesso ginocchio in passato ha mostrato un punteggio funzionale leggermente più basso.", "Non è un motivo per preoccuparsi, ma un buon argomento per raccontare al chirurgo, prima dell'intervento, ogni operazione fatta in precedenza su quel ginocchio."]}, "instagram": {"chir": ["🇮🇹 Rizzoli, Bologna: 168 UKA mediali, sopravvivenza 100/96/86/78% a 5/7/10/15 anni.", "Comorbidità: nessuna associazione con revisione. Chirurgia pregressa: KSS più basso, trend a più complicanze (p=0,054).", "Un dato da portare nel colloquio preoperatorio, non ancora una dimostrazione."], "misto": ["🇮🇹 Uno studio italiano segue 168 protesi parziali di ginocchio fino a 15 anni: risultati solidi nel tempo.", "Le malattie associate non sembrano cambiare il rischio da sole. Chi aveva già operato quel ginocchio mostra un segnale da approfondire.", "Il messaggio: la storia chirurgica del ginocchio conta nel colloquio prima dell'intervento."], "pazienti": ["🇮🇹 168 persone operate di protesi parziale seguite fino a 15 anni: risultati molto buoni.", "Altre malattie non sembrano peggiorare l'esito. Chi aveva già subito un intervento su quel ginocchio ha avuto risultati un po' meno buoni.", "Parlane sempre col tuo chirurgo prima dell'intervento — non è un allarme."]}}, "3": {"video": {"chir": ["Trecentodiciannove pazienti operati di legamento crociato anteriore con innesto di semitendinoso, seguiti fino a due anni con radiografie sotto stress: più è ripido lo slope tibiale mediale, misurato su radiografia laterale, più cresce nel tempo la traslazione tibiale anteriore residua rispetto al ginocchio sano, passando da circa tre millimetri a due mesi fino quasi a sette millimetri a due anni.", "La correlazione è statisticamente significativa ma numericamente debole, ed è comunque un predittore indipendente in analisi multivariabile. Un dato pratico più che teorico: chi aveva anche un rinforzo laterale extra-articolare associato mostra una traslazione residua più bassa a due anni, 6,1 contro 7,3 millimetri, una differenza piccola ma con significatività statistica raggiunta su un campione di questa dimensione.", "Lo studio è condotto solo su innesto di semitendinoso, non sul tendine quadricipitale che usi tu, e non descrive il tipo esatto di costrutto per il rinforzo laterale impiegato. Non chiude quindi le domande sul tuo innesto rigido né sul tuo costrutto onlay superficiale, ma va nella stessa direzione della tua indicazione universale al rinforzo laterale su ogni paziente operato di legamento crociato."], "misto": ["Uno studio francese, condotto a Marsiglia su oltre trecento pazienti operati di legamento crociato anteriore, mostra che un ginocchio con più pendenza naturale della tibia — una caratteristica anatomica individuale, non una scelta chirurgica — tende, nel tempo, a mantenere un po' più di lassità residua rispetto al ginocchio sano non operato.", "L'effetto cresce lentamente nei primi due anni dopo l'intervento, mano a mano che il ginocchio riprende le sue normali attività quotidiane e sportive. Aggiungere un rinforzo laterale al lato del ginocchio durante lo stesso intervento sembra ridurre questo effetto nel tempo: chi lo aveva ricevuto mostrava, al controllo di due anni, una lassità residua misurabile più bassa rispetto a chi non lo aveva ricevuto.", "È uno studio condotto su un solo tipo di innesto, non su tutti quelli oggi in uso nei diversi centri chirurgici: un tassello in più nella conoscenza, non una risposta definitiva, sul valore reale del rinforzo laterale nella ricostruzione del legamento crociato anteriore, soprattutto quando l'innesto scelto è diverso da quello studiato qui."], "pazienti": ["Uno studio francese su oltre trecento pazienti operati di legamento crociato anteriore ha guardato la forma naturale dell'osso della tibia, che varia leggermente da persona a persona per motivi puramente anatomici, senza che nessuno possa modificarla con l'intervento chirurgico.", "Nei pazienti con una tibia dalla forma più inclinata, il ginocchio operato tende ad avere, con il passare del tempo, un pochino più di gioco rispetto al ginocchio sano — una differenza piccola, misurabile solo con strumenti radiografici di precisione, non percepibile nella vita di tutti i giorni.", "Aggiungere un piccolo gesto chirurgico di rinforzo sul lato del ginocchio, durante lo stesso intervento al legamento crociato, sembra ridurre questo effetto nel tempo. È un motivo in più, se il tuo chirurgo te lo propone durante l'intervento, per non considerarlo un passaggio superfluo o puramente precauzionale."]}, "reel": {"chir": ["[319 pazienti · hamstring] Più slope tibiale mediale, più traslazione anteriore residua nel tempo dopo LCA.", "r=0,3 a 2 anni, predittore indipendente (p<0,01). Con LET: 6,1 vs 7,3mm a 2 anni (p=0,009).", "[Non il tuo innesto, non il tuo costrutto] Ma un altro tassello a favore del rinforzo laterale."], "misto": ["[319 pazienti, Francia] Più pendenza naturale della tibia, più lassità residua dopo LCA — effetto piccolo ma reale.", "Chi aveva anche un rinforzo laterale mostrava meno lassità residua a due anni.", "[Un tassello, non una risposta definitiva] Sul valore del rinforzo laterale nella ricostruzione del crociato."], "pazienti": ["[Studio francese, 319 pazienti] La forma naturale della tibia influenza un po' il risultato dopo l'intervento al crociato.", "Chi ha più pendenza tibiale ha un ginocchio con un filo di gioco in più nel tempo — differenza piccola.", "[Un piccolo gesto in più] Il rinforzo laterale sembra ridurre questo effetto."]}, "linkedin": {"chir": ["Paul, Jacquet, Ollivier (Marsiglia), KSSTA: 319 ACLR primarie con autoinnesto di semitendinoso. ATT operato 5,8±3,5mm pre-op → 2,9±2,3 (2 mesi) → 4,9±2,8 (1 anno) → 6,8±4,0mm (2 anni).", "Slope tibiale mediale correlato con ATT SSD a 1 anno (r=0,2; p=0,001) e 2 anni (r=0,3; p<0,001); predittore indipendente in multivariabile (p<0,01). Età (p=0,009) e lesioni cartilaginee mediali (p=0,008) associate a maggiore lassità precoce. LET associato a ATT SSD più bassa a 2 anni (6,1 vs 7,3mm; p=0,009).", "Limiti: solo autoinnesto di semitendinoso, non verificato su tendine quadricipitale/retto femorale; costrutto del LET non descritto. Alimenta la tensione sul rinforzo laterale universale su innesto rigido: la direzione è coerente, la trasferibilità diretta resta da dimostrare."], "misto": ["Uno studio francese su 319 pazienti operati di legamento crociato anteriore mostra che lo slope tibiale — la pendenza naturale della tibia — si associa a una lassità residua che cresce lentamente nel tempo.", "L'effetto è debole ma statisticamente indipendente. Il dato pratico: chi aveva anche un rinforzo laterale mostrava, a due anni, una lassità residua più bassa (6,1 contro 7,3mm).", "Limite dichiarato: solo un tipo di innesto (hamstring), non il tendine quadricipitale sempre più usato in molti centri. Un tassello che va nella direzione dell'uso del rinforzo laterale, non una prova definitiva su ogni innesto."], "pazienti": ["Uno studio su oltre 300 pazienti operati di legamento crociato anteriore mostra che la forma naturale dell'osso della tibia può influenzare, in piccola parte, il risultato nel tempo.", "Chi ha una tibia con più pendenza tende ad avere un filo di gioco in più nel ginocchio operato — una differenza piccola, misurata con strumenti di precisione.", "Aggiungere un piccolo gesto di rinforzo laterale durante l'intervento sembra ridurre questo effetto: se il tuo chirurgo te lo propone, non è un passaggio superfluo."]}, "instagram": {"chir": ["🇫🇷 319 ACLR, hamstring: slope tibiale mediale ↑ → ATT residua ↑ nel tempo (r=0,3 a 2 anni).", "Con LET: ATT SSD più bassa a 2 anni (6,1 vs 7,3mm; p=0,009).", "Non il tuo innesto, non il tuo costrutto — ma coerente con l'indicazione universale al rinforzo laterale."], "misto": ["🇫🇷 319 pazienti operati di crociato: più pendenza tibiale naturale, più lassità residua nel tempo.", "Chi aveva anche un rinforzo laterale mostrava meno lassità a due anni.", "Un tassello in più sul valore del rinforzo laterale nella ricostruzione."], "pazienti": ["🇫🇷 Studio su 319 pazienti: la forma naturale della tibia può influenzare un po' il risultato dopo l'intervento al crociato.", "Piccola differenza, misurabile solo con strumenti di precisione.", "Un piccolo gesto di rinforzo in più durante l'intervento sembra aiutare."]}}, "4": {"video": {"chir": ["Duecentottantuno riparazioni primarie del legamento crociato anteriore, con tecnica selettiva e ancora a doppia sutura, tutte eseguite da un solo chirurgo dell'Hospital for Special Surgery di New York fra il 2008 e il 2021: il fallimento a due-cinque anni riguarda il dieci per cento dei duecentotrentaquattro pazienti seguiti fino in fondo.", "Due predittori indipendenti emergono dall'analisi multivariata: l'integrità della guaina sinoviale intorno al legamento residuo, se scesa sotto il cinquanta per cento all'ispezione artroscopica, quasi triplica il rischio di fallimento con un odds ratio di 3,31; e l'età più giovane del paziente, che aumenta il rischio del sei per cento per ogni anno in meno di età al momento dell'intervento.", "Tu non esegui questa tecnica — operi ricostruzione con innesto, non riparazione diretta del legamento — ma è il lavoro più recente e più ampio del gruppo di riferimento mondiale per questo approccio, Gregory DiFelice all'Hospital for Special Surgery: utile sapere quali pazienti falliscono di più, per il colloquio quando qualcuno te ne chiede conto in ambulatorio."], "misto": ["Uno studio americano condotto su oltre duecentottanta pazienti guarda a una tecnica alternativa rispetto alla ricostruzione classica del legamento crociato: la sutura diretta del legamento lesionato, invece di sostituirlo con un nuovo tendine prelevato altrove nel ginocchio, quando le caratteristiche della lesione lo permettono davvero.", "A due-cinque anni dall'intervento, circa un paziente su dieci ha avuto un fallimento della riparazione, cioè il legamento non ha tenuto nel tempo. Il rischio risulta più alto quando la guaina naturale che avvolge il legamento è più danneggiata al momento dell'intervento, e nei pazienti più giovani rispetto a quelli di età più avanzata.", "È una tecnica selettiva, riservata a lesioni con caratteristiche anatomiche molto precise, eseguita solo in centri specializzati con grande esperienza specifica: non sostituisce la ricostruzione standard nella maggior parte dei casi, ma questo studio aiuta a capire meglio per quali pazienti questa alternativa potrebbe non essere la scelta più solida."], "pazienti": ["Un centro americano molto specializzato, l'Hospital for Special Surgery di New York, ha studiato su oltre duecentottanta pazienti una tecnica diversa dalla ricostruzione classica del legamento crociato: ricucire direttamente il legamento lesionato invece di sostituirlo con un nuovo tendine prelevato altrove.", "Dopo un periodo di due-cinque anni dall'operazione, in circa un caso su dieci l'intervento non ha tenuto nel tempo come sperato. Il rischio è risultato più alto quando il tessuto naturale attorno al legamento era più danneggiato fin dall'inizio, e nei pazienti più giovani rispetto a quelli più avanti con l'età.", "Questa tecnica si usa solo per lesioni con caratteristiche molto specifiche, valutate caso per caso da chirurghi con esperienza dedicata: se il tuo chirurgo te ne parla come possibilità, è del tutto normale e sensato chiedere se il tuo tipo esatto di lesione è davvero adatto a questo approccio alternativo."]}, "reel": {"chir": ["[281 riparazioni primarie LCA · HSS] Tecnica DiFelice, ancora a doppia sutura, singolo chirurgo.", "Fallimento 10% (24/234) a 2-5 anni. Guaina sinoviale <50%: OR 3,31 (p=0,049). Età: +6%/anno più giovane.", "[Tecnica che non esegui] Ma il riferimento mondiale per chi te ne chiede conto."], "misto": ["[281 pazienti, USA] Sutura diretta del crociato invece della ricostruzione classica: una tecnica alternativa e selettiva.", "Un fallimento su dieci a 2-5 anni. Più frequente con tessuto danneggiato e nei pazienti più giovani.", "[Non sostituisce la ricostruzione] Aiuta a capire per chi potrebbe non essere la scelta giusta."], "pazienti": ["[Studio USA, 281 pazienti] Ricucire il crociato invece di sostituirlo: una tecnica riservata a casi precisi.", "In un caso su dieci non ha tenuto dopo 2-5 anni, più spesso nei pazienti più giovani.", "[Se te ne parlano] Chiedi se la tua lesione è adatta a questa tecnica."]}, "linkedin": {"chir": ["von Rehlingen-Prinz, DiFelice et al. (Hospital for Special Surgery), Arthroscopy: 281 riparazioni primarie del LCA (Sherman I-II), ancora a doppia sutura, singolo chirurgo 2008-2021. 234/281 (92%) con follow-up 2-5 anni.", "24 fallimenti (10%). Multivariata: integrità della guaina sinoviale <50% → OR 3,31 (p=0,049); età più giovane → +6% di rischio/anno (p<0,001). Bassa integrità sinoviale correlata a pattern di rottura più complesso (p<0,001), a sua volta associato a PROM peggiori a 2 anni. Kappa interosservatore 0,734-0,956.", "Limiti: livello III, singolo chirurgo/centro, selezione rigorosa (lesioni prossimali, tessuto di buona qualità). Non generalizzabile a ogni rottura del LCA. Tecnica che non rientra nella tua pratica, ma dal gruppo di riferimento per la riparazione primaria — utile per il colloquio quando un paziente la richiede."], "misto": ["Un centro americano specializzato pubblica i risultati a 2-5 anni di 281 riparazioni dirette del legamento crociato anteriore — un'alternativa selettiva alla ricostruzione classica, su lesioni con caratteristiche precise.", "Il fallimento riguarda un paziente su dieci, più frequente quando il tessuto attorno al legamento è più danneggiato e nei pazienti più giovani — due fattori che uno specialista può valutare prima di proporre questa tecnica.", "Limite dichiarato: selezione rigorosa dei candidati in un solo centro, quindi non generalizzabile a ogni lesione. Un dato utile soprattutto per capire quando questa tecnica non è la scelta più solida."], "pazienti": ["Un ospedale americano molto specializzato ha seguito per 2-5 anni 281 pazienti operati con una tecnica che ricuce il legamento crociato invece di sostituirlo con un nuovo tendine.", "In circa un caso su dieci l'intervento non ha tenuto nel tempo, più spesso quando il tessuto era più danneggiato o nei pazienti più giovani.", "È una tecnica per casi selezionati, non per tutte le lesioni: se il tuo chirurgo te la propone, è del tutto normale chiedere perché la considera adatta al tuo caso."]}, "instagram": {"chir": ["🇺🇸 HSS: 281 riparazioni primarie LCA, tecnica DiFelice, singolo chirurgo 2008-2021.", "Fallimento 10% a 2-5 anni. Guaina sinoviale <50%: OR 3,31. Età più giovane: +6%/anno.", "Non è la tua tecnica, ma il riferimento mondiale su questo approccio."], "misto": ["🇺🇸 Un centro USA specializzato: 281 pazienti con sutura diretta del crociato, non ricostruzione.", "Un fallimento su dieci a 2-5 anni, più spesso con tessuto danneggiato o pazienti giovani.", "Tecnica selettiva, non un'alternativa per tutti."], "pazienti": ["🇺🇸 Studio su 281 pazienti: ricucire il crociato invece di sostituirlo, su casi selezionati.", "In un caso su dieci non ha tenuto dopo 2-5 anni.", "Chiedi sempre al chirurgo se la tua lesione è adatta a questa tecnica."]}}, "5": {"video": {"chir": ["Uno studio olandese condotto a Utrecht su venti pazienti operati di osteotomia tibiale alta confronta due modi diversi di misurare l'allineamento della gamba sulla radiografia: il centro anatomico del ginocchio, che è il metodo classico tradizionale, contro un punto di carico laterale al 62,5%, che è il vero bersaglio chirurgico della correzione in valgo che si vuole ottenere.", "Cambiando semplicemente il punto di riferimento usato per la stessa identica radiografia, tutti gli angoli di allineamento si spostano in modo significativo — anche di quasi due gradi per ciascun parametro misurato — e la classificazione della deformità femorale cambia completamente in circa un caso su tre dei venti pazienti analizzati in questo studio.", "È solo un confronto metodologico di misura, senza alcun dato clinico sui risultati dell'intervento: ma se pianifichi una correzione di slope o di asse della gamba nella tua pratica quotidiana, questo studio suggerisce di guardare con attenzione da quale punto di riferimento nasce la classificazione della deformità, che potrebbe essere diverso da quello che forse usi abitualmente oggi."], "misto": ["Uno studio olandese condotto su venti pazienti operati di correzione dell'asse della gamba mostra che il modo in cui si misura la deformità sulla radiografia — partendo dal centro del ginocchio oppure da un punto più spostato verso l'esterno — può cambiare in modo sostanziale il risultato della misura stessa, anche sulla stessa identica immagine radiografica.", "In circa un caso su tre, il tipo di deformità attribuito al femore cambia completamente a seconda di quale dei due metodi di misura viene utilizzato dal chirurgo durante la fase di pianificazione preoperatoria dell'intervento correttivo.", "È uno studio piccolo e limitato solo alla fase di misura, non ancora collegato ai risultati clinici reali dei pazienti operati: resta comunque un invito concreto a discutere con il proprio chirurgo quale metodo di pianificazione radiografica utilizza abitualmente prima di un intervento di correzione dell'asse della gamba."], "pazienti": ["Uno studio olandese su venti pazienti operati per correggere l'asse della gamba mostra che il modo in cui si misura la deformità sulla radiografia, prima ancora di operare, può cambiare il giudizio medico su dove nasce esattamente il problema anatomico da correggere chirurgicamente.", "In circa un caso su tre dei pazienti analizzati, cambiando semplicemente il metodo di misura usato sulla stessa radiografia, la parte dell'osso ritenuta più deformata risulta diversa rispetto a quanto si sarebbe concluso con il metodo tradizionale più comunemente usato.", "È un dato tecnico che riguarda soprattutto la fase di pianificazione dell'intervento, più che il risultato finale dell'operazione stessa: non deve preoccupare chi deve operarsi presto, ma mostra quanto sia delicata e importante la fase di misurazione accurata che precede ogni intervento di questo tipo."]}, "reel": {"chir": ["[20 pazienti · HTO] Centro del ginocchio vs punto di carico laterale: stesso paziente, misure diverse.", "mLDFA +1,52°, mMPTA -1,84°, mLDTA -1,85° (tutti p<0,001). Riclassificazione: femori varo 4→10/20.", "[Solo un confronto di misura] Ma rilevante per come pianifichi la correzione."], "misto": ["[20 pazienti, Olanda] Come si misura la deformità della gamba cambia il risultato della misura stessa.", "In un caso su tre il tipo di deformità del femore cambia completamente col metodo usato.", "[Studio di misura, non di esito clinico] Un invito a discuterne col chirurgo prima di un intervento di correzione."], "pazienti": ["[20 pazienti operati] Il modo di misurare la deformità della gamba prima dell'intervento può cambiare il giudizio.", "In un caso su tre il risultato della misura cambia a seconda del metodo.", "[Solo una questione tecnica] Riguarda la pianificazione, non il risultato finale dell'intervento."]}, "linkedin": {"chir": ["Fuller, Custers et al. (Utrecht), Cartilage: 20 pazienti con artrosi monocompartimentale mediale candidati a HTO valgizzante, confronto fra centro anatomico del ginocchio e punto di carico laterale al 62,5% per l'analisi dell'allineamento.", "Rispetto al metodo centrato sul ginocchio: mLDFA +1,52° (più varo), mMPTA -1,84° (più varo), mLDTA -1,85° (più valgo), tutti p<0,001. Riclassificazione della deformità: femori in varo da 4 a 10/20, tibie da 8 a 13/20.", "Limiti: 20 pazienti, nessun esito clinico riportato, nessun confronto con riferimento TC 3D. Rilevante per la pianificazione preoperatoria delle osteotomie: il punto di riferimento scelto per l'analisi radiografica può rivelare deformità femorali sottostimate dal metodo tradizionale."], "misto": ["Uno studio olandese su 20 pazienti candidati a osteotomia correttiva del ginocchio mostra che il modo in cui si misura l'allineamento della gamba cambia il risultato della misura stessa.", "Usando come riferimento il punto di carico laterale invece del centro del ginocchio, tutti gli angoli si spostano, e in un caso su tre il tipo di deformità del femore risulta diverso.", "È uno studio piccolo, solo di misura, senza dati su come questo cambi l'esito clinico: ma è un tassello utile per chi pianifica una correzione dell'asse della gamba."], "pazienti": ["Uno studio su 20 pazienti candidati a un intervento di correzione dell'asse della gamba mostra quanto sia delicata la fase di misurazione prima dell'operazione.", "A seconda del punto di riferimento scelto sulla radiografia, la parte dell'osso giudicata più deformata può cambiare — in un caso su tre per il femore.", "È un aspetto tecnico della pianificazione, non un motivo di preoccupazione per chi deve operarsi: mostra quanta cura richiede la fase che precede l'intervento."]}, "instagram": {"chir": ["🇳🇱 20 pazienti HTO: centro del ginocchio vs punto di carico laterale, stessa gamba, misure diverse.", "mLDFA/mMPTA/mLDTA tutti p<0,001. Riclassificazione femorale in 6/20 casi.", "Un tassello per la pianificazione preoperatoria delle osteotomie."], "misto": ["🇳🇱 20 pazienti: il modo di misurare la deformità della gamba cambia il risultato della misura.", "In un caso su tre il tipo di deformità del femore cambia col metodo usato.", "Studio di misura, non ancora di esito clinico."], "pazienti": ["🇳🇱 20 pazienti: misurare la gamba in modo diverso può cambiare il giudizio sulla deformità.", "In un caso su tre il risultato cambia a seconda del metodo.", "Riguarda la pianificazione, non il risultato dell'intervento."]}}, "6": {"video": {"chir": ["Novanta ginocchia analizzate su risonanza magnetica, divise in tre gruppi pediatrici appaiati per età e sesso, trenta ginocchia per ciascun gruppo: nell'osteocondrite dissecante del condilo femorale laterale, il fascio postero-laterale del legamento crociato anteriore si inserisce in un punto significativamente più basso e più orizzontale rispetto ai due gruppi di controllo confrontati nello stesso studio.", "La differenza è statisticamente netta, sia quando misurata rispetto all'altezza della cartilagine di accrescimento sia quando misurata rispetto all'altezza del condilo femorale laterale stesso, con una significatività forte in entrambe le misurazioni indipendenti effettuate dai ricercatori su tutte e novanta le ginocchia incluse nello studio.", "Non riguarda direttamente il tuo lavoro chirurgico quotidiano — qui il legamento crociato è integro in tutti i pazienti, e la popolazione studiata è in gran parte sotto i quattordici anni di età che tu operi abitualmente — ma aiuta a capire meglio l'anatomia normale del fascio postero-laterale, utile quando incontri un'osteocondrite dissecante negli adolescenti al limite della tua fascia di pratica clinica."], "misto": ["Uno studio condotto su novanta ginocchia di ragazzi, in tre centri diversi fra Basilea e Stanford, mostra una possibile connessione anatomica fra la posizione di uno dei due fasci del legamento crociato anteriore e una lesione della cartilagine chiamata osteocondrite dissecante, che colpisce soprattutto i più giovani durante la crescita.", "Nei ragazzi con questa lesione localizzata sul lato esterno del ginocchio, uno dei due fasci del legamento crociato anteriore, quello postero-laterale, si inserisce in un punto anatomico diverso rispetto a chi non ha questa stessa lesione, sia nel gruppo di controllo sano sia nel gruppo con la lesione sul lato opposto.", "È uno studio di anatomia descrittiva, non su un intervento chirurgico specifico: aiuta soprattutto a capire meglio una condizione della cartilagine che colpisce bambini e adolescenti in fase di crescita, più che a cambiare qualcosa nella pratica quotidiana di un chirurgo che opera prevalentemente pazienti adulti."], "pazienti": ["Uno studio su novanta ginocchia di ragazzi, condotto in due ospedali specializzati fra Svizzera e Stati Uniti, ha guardato da vicino una lesione della cartilagine chiamata osteocondrite dissecante, che colpisce soprattutto bambini e adolescenti ancora in piena fase di crescita ossea.", "I ricercatori hanno trovato che, nei ragazzi con questa lesione su un lato specifico del ginocchio, un legamento interno all'articolazione ha una forma di inserzione leggermente diversa rispetto a chi non ha questa stessa lesione, una differenza visibile solo con la risonanza magnetica.", "È uno studio che serve soprattutto a capire meglio come nasce questa particolare lesione nei pazienti più giovani durante la crescita: non riguarda un intervento chirurgico da programmare né una scelta terapeutica da fare oggi per un paziente adulto già in cura."]}, "reel": {"chir": ["[90 ginocchia · 3 coorti pediatriche] OCD condilo laterale: fascio PL del LCA più basso e orizzontale.", "0,36 vs 0,43 vs 0,43 (relativo al condilo), p<0,001. Stessa direzione relativa alla fisi.", "[Non la tua pratica] Ma utile per l'anatomia del fascio PL negli adolescenti."], "misto": ["[90 ginocchia, ragazzi] Una lesione della cartilagine e la posizione di un fascio del crociato: una connessione anatomica.", "Chi ha la lesione sul lato esterno ha il fascio inserito in un punto diverso.", "[Studio di anatomia] Non su un intervento, ma utile per capire una condizione degli adolescenti."], "pazienti": ["[90 ginocchia di ragazzi] Uno studio su una lesione della cartilagine che colpisce i più giovani.", "Trovata una piccola differenza anatomica in chi ha questa lesione.", "[Solo per capire meglio] Non riguarda una scelta chirurgica da fare oggi."]}, "linkedin": {"chir": ["Lehoczky, Khoo, Shea (Basel/Stanford), AJSM: caso-controllo su 90 ginocchia, 3 coorti appaiate per età/sesso (OCD condilo laterale, OCD condilo mediale, controlli sani), età media 12,5 anni (8-16).", "Altezza di inserzione del fascio postero-laterale del LCA significativamente diversa fra i gruppi (p<0,001 su entrambe le misure): nell'OCD del condilo laterale l'inserzione è più bassa — 0,36±0,06 relativa al condilo, 0,46±0,07 relativa alla fisi — contro 0,43-0,43/0,50-0,55 negli altri due gruppi.", "Limiti: livello III, associazione anatomica non causale, popolazione in parte sotto i 14 anni. Non tocca la tua pratica diretta (LCA integro), ma rilevante per l'anatomia del fascio postero-laterale e il sospetto diagnostico nell'adolescente con OCD del condilo laterale."], "misto": ["Uno studio su 90 ginocchia di ragazzi confronta l'anatomia del legamento crociato anteriore in chi ha un'osteocondrite dissecante del condilo laterale rispetto a chi non ce l'ha.", "Il fascio postero-laterale del legamento si inserisce in un punto significativamente diverso, più basso e più orizzontale, in chi ha questa lesione.", "È uno studio di anatomia su una popolazione in gran parte pediatrica: non cambia la pratica di un chirurgo adulto, ma aiuta a capire meglio una lesione della cartilagine tipica della crescita."], "pazienti": ["Uno studio su 90 ginocchia di ragazzi guarda a una lesione della cartilagine chiamata osteocondrite dissecante, frequente durante la crescita.", "È stata trovata una piccola differenza anatomica in un legamento del ginocchio, in chi ha questa lesione su un lato specifico.", "Non riguarda una decisione chirurgica da prendere oggi: serve a capire meglio come nasce questa condizione nei più giovani."]}, "instagram": {"chir": ["🧬 90 ginocchia, 3 coorti pediatriche: OCD condilo laterale associata a fascio PL del LCA più orizzontale.", "p<0,001 su entrambe le misure di altezza di inserzione.", "Non la tua pratica (LCA integro), ma utile per il sospetto diagnostico negli adolescenti."], "misto": ["🧬 90 ginocchia di ragazzi: connessione fra una lesione della cartilagine e l'anatomia di un legamento.", "Il fascio si inserisce diversamente in chi ha la lesione sul lato esterno.", "Studio di anatomia, utile per capire una condizione della crescita."], "pazienti": ["🧬 90 ginocchia di ragazzi: uno studio su una lesione della cartilagine tipica della crescita.", "Trovata una piccola differenza anatomica in chi ce l'ha.", "Non riguarda una scelta chirurgica da fare oggi."]}}};
var TAGS={"1": {"linkedin": "#ArtroplasticaGinocchio #ERAS #ChirurgiaOrtopedica", "instagram": "#protesiginocchio #protesianca #recuperorapido #ERAS #ortopedia #chirurgiaortopedica #ESSKA #riabilitazione #ginocchio #anca #chirurgiaprotesica #medicinasportiva", "kw": "protesi ginocchio recupero rapido"}, "2": {"linkedin": "#ProtesiGinocchio #ChirurgiaOrtopedica #Ginocchio", "instagram": "#protesiginocchio #protesiparziale #ginocchio #ortopedia #chirurgiaortopedica #artrosi #chirurgiadelginocchio #medicinasportiva #saluteginocchio #Bologna #Rizzoli #recuperolungotermine", "kw": "protesi parziale ginocchio durata nel tempo"}, "3": {"linkedin": "#LegamentoCrociato #ChirurgiaGinocchio #Ortopedia", "instagram": "#legamentocrociato #lca #ginocchio #chirurgiaortopedica #ricostruzionelca #sport #medicinasportiva #ortopedia #rientroallosport #stabilitadelginocchio #chirurgiadelginocchio #ginocchiodellosportivo", "kw": "ricostruzione legamento crociato stabilità nel tempo"}, "4": {"linkedin": "#LegamentoCrociato #ChirurgiaGinocchio #Ortopedia", "instagram": "#legamentocrociato #lca #riparazioneprimaria #ginocchio #chirurgiaortopedica #ortopedia #medicinasportiva #chirurgiadelginocchio #sport #ricostruzionelca #ginocchiodellosportivo #innovazionechirurgica", "kw": "riparazione primaria legamento crociato anteriore"}, "5": {"linkedin": "#Osteotomia #ChirurgiaGinocchio #Ortopedia", "instagram": "#osteotomia #ginocchio #artrosi #chirurgiaortopedica #correzionedellasse #ortopedia #chirurgiadelginocchio #medicinasportiva #pianificazionechirurgica #ginocchiovaro #saluteginocchio #chirurgiapreservativa", "kw": "osteotomia tibiale correzione asse gamba"}, "6": {"linkedin": "#Ginocchio #Ortopedia #MedicinaSportiva", "instagram": "#osteocondrite #ginocchio #ortopediapediatrica #adolescenti #legamentocrociato #chirurgiaortopedica #medicinasportiva #cartilagine #crescita #sportgiovanile #saluteginocchio #ortopedia", "kw": "osteocondrite dissecante ginocchio adolescenti"}};
var NLB={"1": {"prof": ["Consenso ESSKA/EKA su fast-track in protesi di anca e ginocchio", "Centosei esperti internazionali hanno formalizzato 63 raccomandazioni sul percorso di recupero rapido perioperatorio in artroplastica di anca e ginocchio, 39 delle quali basate su evidenza di livello alto.", "24 raccomandazioni su 63 restano opinione di esperti non ancora sostenuta da evidenza di livello alto, e nessuna è specifica per singola piattaforma robotica."], "mix": ["Un consenso internazionale sul recupero rapido dopo protesi di ginocchio e anca", "Centosei specialisti nel mondo hanno messo per iscritto come organizzare al meglio il periodo prima, durante e dopo un intervento di protesi, in 63 raccomandazioni pratiche.", "Non riguarda la tecnica chirurgica in sé, e una parte delle raccomandazioni resta opinione di esperti più che dimostrazione scientifica solida."], "paz": ["Le buone pratiche internazionali per un buon recupero dopo la protesi", "Centosei specialisti hanno definito insieme le buone pratiche per il periodo attorno a un intervento di protesi d'anca o di ginocchio, per aiutare a tornare a muoversi prima e in sicurezza.", "Non cambia il modo in cui si opera, riguarda l'organizzazione del percorso attorno all'intervento: parlane con il tuo chirurgo prima di operarti."], "kw": "protesi ginocchio recupero rapido"}, "2": {"prof": ["La monocompartimentale tiene fino a 15 anni, dati del Rizzoli", "168 protesi monocompartimentali mediali seguite fino a 15 anni: sopravvivenza 100% a 5 anni, 96% a 7, 86% a 10, 78% a 15; nessuna comorbidità associata in modo significativo alla revisione.", "Chi aveva già subito un intervento sullo stesso ginocchio mostra un punteggio clinico più basso e una tendenza — non significativa (p=0,054) — a più complicanze: un segnale, non una dimostrazione."], "mix": ["Protesi parziale di ginocchio: buoni risultati fino a 15 anni", "Un centro italiano di riferimento segue 168 protesi parziali di ginocchio per fino a quindici anni, con una sopravvivenza che resta alta a ogni intervallo di tempo controllato.", "Chi aveva già subito un intervento sullo stesso ginocchio mostra un punteggio funzionale un po' più basso: un segnale da tenere d'occhio, non ancora una certezza statistica."], "paz": ["Protesi parziale di ginocchio: come si comporta nel tempo", "Uno studio italiano ha seguito 168 persone operate di protesi parziale di ginocchio per fino a quindici anni, con risultati molto solidi nel tempo.", "Avere altre malattie non sembra peggiorare l'esito. Chi aveva già subito un intervento su quel ginocchio ha avuto risultati un po' meno buoni: parlane sempre con il tuo chirurgo prima di operarti."], "kw": "protesi parziale ginocchio durata nel tempo"}, "3": {"prof": ["Slope tibiale e lassità residua dopo LCA: il rinforzo laterale aiuta", "319 pazienti operati di LCA con hamstring: uno slope tibiale mediale più ripido predice, in modo indipendente, una maggiore traslazione tibiale anteriore residua nel tempo; il rinforzo laterale ne attenua l'effetto.", "Solo autoinnesto di semitendinoso, costrutto del rinforzo laterale non descritto: non verificato sul tendine quadricipitale né sul costrutto onlay, correlazioni statisticamente deboli (r=0,2-0,3)."], "mix": ["La forma della tibia e la stabilità del ginocchio dopo il crociato", "Uno studio francese su oltre 300 pazienti mostra che un ginocchio con più pendenza naturale della tibia tende, nel tempo, a mantenere un po' più di lassità residua dopo la ricostruzione del legamento crociato.", "È uno studio su un solo tipo di innesto: un tassello in più, non una risposta definitiva, sul valore del rinforzo laterale nella ricostruzione."], "paz": ["Perché la forma della tibia conta dopo l'intervento al crociato", "Uno studio su oltre 300 pazienti operati di legamento crociato anteriore mostra che la forma naturale dell'osso della tibia può influenzare, in piccola parte, il risultato nel tempo.", "Aggiungere un piccolo gesto di rinforzo laterale durante l'intervento sembra ridurre questo effetto: se il tuo chirurgo te lo propone, non è un passaggio superfluo."], "kw": "ricostruzione legamento crociato stabilità nel tempo"}, "4": {"prof": ["La guaina sinoviale predice il fallimento della riparazione del LCA", "281 riparazioni primarie del LCA (tecnica selettiva, HSS): integrità della guaina sinoviale sotto il 50% ed età più giovane predicono in modo indipendente il fallimento, presente nel 10% dei casi a 2-5 anni.", "Livello III, singolo chirurgo e centro, selezione rigorosa dei candidati: non generalizzabile a ogni rottura del LCA, e tecnica non equivalente alla ricostruzione standard."], "mix": ["Ricucire il crociato invece di sostituirlo: quando funziona meno", "Un centro americano specializzato studia, su oltre 280 pazienti, una tecnica alternativa alla ricostruzione classica del crociato: la sutura diretta del legamento, quando la lesione lo permette.", "È una tecnica selettiva, riservata a lesioni con caratteristiche precise: non sostituisce la ricostruzione standard, ma aiuta a capire per quali pazienti potrebbe non essere la scelta giusta."], "paz": ["Quando si può ricucire il legamento crociato invece di sostituirlo", "Un centro americano molto specializzato ha studiato, su oltre 280 pazienti, una tecnica diversa dalla ricostruzione classica del legamento crociato: ricucire il legamento invece di sostituirlo con un nuovo tendine.", "Questa tecnica si usa solo per lesioni con caratteristiche molto specifiche: se te ne parlano, è normale chiedere se il tuo tipo di lesione è adatto."], "kw": "riparazione primaria legamento crociato anteriore"}, "5": {"prof": ["Come si misura la deformità prima di un'osteotomia cambia il giudizio", "In 20 pazienti candidati a osteotomia tibiale alta, misurare l'allineamento dal punto di carico laterale invece che dal centro del ginocchio sposta tutti i parametri angolari (tutti p<0,001) e riclassifica la deformità in un terzo dei femori.", "20 pazienti, nessun esito clinico riportato, nessun confronto con riferimento TC 3D: dimostra un effetto sulla misura, non ancora un impatto su pianificazione o risultato chirurgico."], "mix": ["Perché il punto di riferimento conta nella correzione dell'asse della gamba", "Uno studio su venti pazienti candidati a un intervento di correzione dell'asse della gamba mostra che il modo in cui si misura la deformità cambia il risultato della misura stessa.", "È uno studio piccolo, solo di misura, senza dati su come questo cambi l'esito clinico: un tassello utile per chi pianifica l'intervento, non ancora una certezza sui risultati."], "paz": ["La misurazione prima di un intervento di correzione della gamba", "Uno studio su venti pazienti candidati a un intervento di correzione dell'asse della gamba mostra quanto sia delicata la fase di misurazione prima dell'operazione.", "È un aspetto tecnico della pianificazione, non un motivo di preoccupazione per chi deve operarsi: mostra quanta cura richiede la fase che precede l'intervento."], "kw": "osteotomia tibiale correzione asse gamba"}, "6": {"prof": ["Osteocondrite dissecante laterale e anatomia del fascio postero-laterale del LCA", "In 90 ginocchia pediatriche, l'osteocondrite dissecante del condilo femorale laterale si associa a un'inserzione più bassa e più orizzontale del fascio postero-laterale del LCA rispetto ai controlli (p<0,001).", "Studio caso-controllo retrospettivo, livello III: associazione anatomica, non causalità; popolazione in parte sotto i 14 anni, nessun LCA operato in questa coorte."], "mix": ["Una lesione della cartilagine nei ragazzi e l'anatomia del ginocchio", "Uno studio su novanta ginocchia di ragazzi mostra una possibile connessione fra la posizione di uno dei fasci del legamento crociato anteriore e una lesione della cartilagine chiamata osteocondrite dissecante.", "È uno studio di anatomia, non su un intervento chirurgico: aiuta a capire meglio una condizione che colpisce soprattutto bambini e adolescenti."], "paz": ["Una lesione della cartilagine tipica della crescita, spiegata meglio", "Uno studio su novanta ginocchia di ragazzi ha guardato una lesione della cartilagine chiamata osteocondrite dissecante, che colpisce soprattutto bambini e adolescenti in crescita.", "È uno studio che serve a capire meglio come nasce questa lesione nei più giovani, non riguarda un intervento chirurgico né una scelta da fare oggi."], "kw": "osteocondrite dissecante ginocchio adolescenti"}};
var ARTICLES=[{n:1,mono:"m-kssta",dot:"red",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Consenso formale ESSKA/EKA su protesi e recupero rapido",v:"106 esperti, 63 raccomandazioni su percorso fast-track/ERAS per protesi di anca e ginocchio: 39 gradate A o B, 24 C o D, accordo medio 7,7-8,9 su 9.",ax:"Totlis, Kort, Budhiparama",date:"set 2026",meta:"consenso formale internazionale, 106 esperti · [I, autoassegnato]",pmid:'42748364',doi:'10.1002/ksa.70594',journal:"Knee Surgery, Sports Traumatology, Arthroscopy",authors:"Totlis T, Kort N, Kort R, Budhiparama NC, Carulli C, Clarius M, Coden G, Gamie Z, Gomberg B, Grant A, Guenther D, Haddad FS, Kayani B, Kenanidis E, Królikowska A, Liu D, Lumban-Gaol I, Machado L, Nandi S, Pérez-Prieto D, Prill R, Smith E, Tandogan R, Tsiridis E, Van Beek R",design:"Consenso formale internazionale (metodologia Delphi-simile): un gruppo direttivo di 22 esperti ha elaborato 37 domande e le relative affermazioni sulla base della letteratura; un gruppo di valutazione indipendente di 35 esperti ha votato ogni affermazione su scala Likert 1-9 in due round; un gruppo di revisione paritaria di 49 esperti ha verificato l'applicabilità transnazionale del documento finale.",pop:"Non uno studio su pazienti: un documento di consenso su percorsi di recupero rapido (fast-track/ERAS) per protesi totale di anca e di ginocchio, rivolto a chi pratica e organizza l'artroplastica.",results:"Dalle 37 domande sono nate 63 affermazioni: 39 gradate A o B (evidenza di livello alto), 24 C o D (opinione di esperti). Punteggio di accordo medio da 7,7 a 8,9 su una scala 1-9. 56 affermazioni giudicate appropriate con forte accordo, 7 con accordo relativo. Le raccomandazioni coprono la gestione preoperatoria, intraoperatoria e postoperatoria. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract: un documento di consenso misura l'accordo fra esperti, non un effetto clinico.",concl:"Gli autori raccomandano l'adozione di percorsi fast-track/ERAS strutturati come approccio centrato sul paziente in protesi di anca e ginocchio, per ridurre la morbidità, ottimizzare l'analgesia, accorciare la degenza e favorire mobilizzazione e dimissione precoci in sicurezza — un quadro pragmatico che non sostituisce il giudizio clinico.",limits:"24 delle 63 affermazioni restano di grado C o D, cioè opinione di esperti non ancora sostenuta da evidenza di alto livello · un documento di consenso non genera dati clinici propri, sintetizza quelli esistenti · nessuna raccomandazione è specifica per singola piattaforma robotica (VELYS non è nominato).",perte:"Tocca direttamente la tua pratica di protesi totale di ginocchio, non sul piano tecnico-chirurgico ma su come organizzi il percorso perioperatorio attorno all'intervento: è la prima cornice internazionale formalmente concordata da ESSKA/EKA, EHS e APAS su questo terreno, utile per confrontare il tuo protocollo attuale con uno standard emergente."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"International Orthopaedics",h:"La monocompartimentale tiene fino a 15 anni, il Rizzoli lo conferma",v:"168 protesi monocompartimentali mediali: sopravvivenza 100% a 5 anni, 96% a 7, 86% a 10, 78% a 15 — un segnale di cautela, non ancora significativo, sulla chirurgia pregressa dello stesso ginocchio.",ax:"Cerasoli, Grassi, Zaffagnini, Marcheggiani Muccioli",date:"set 2026",meta:"coorte retrospettiva monocentrica, 168 protesi · [III]",pmid:'42744992',doi:'10.1007/s00264-026-07029-1',journal:"International Orthopaedics",authors:"Cerasoli T, Branzanti E, Lo Presti M, Favero A, Fratini S, Mavilla L, Grassi A, Zaffagnini S, Marcheggiani Muccioli GM",design:"Coorte retrospettiva monocentrica (Istituto Ortopedico Rizzoli, Bologna), sopravvivenza dell'impianto dopo protesi monocompartimentale mediale, endpoint di Kaplan-Meier la revisione di qualunque componente; sottocoorte nidificata sottoposta a valutazione clinica ambulatoriale per comorbidità, chirurgia pregressa, complicanze ed esiti funzionali.",pop:"168 protesi monocompartimentali mediali, follow-up medio 119,7±29,3 mesi (circa 10 anni) per l'analisi di sopravvivenza; sottocoorte clinica di 76 ginocchia per l'analisi di comorbidità, chirurgia pregressa ed esiti.",results:"18 revisioni totali. Sopravvivenza dell'impianto: 100% a 5 anni, 96% a 7 anni, 86% a 10 anni, 78% a 15 anni. Nella sottocoorte di 76 ginocchia: 92,1% con almeno una comorbidità, 54,0% con multimorbidità, nessuna categoria di comorbidità associata in modo significativo a revisione o esito a lungo termine. Chirurgia ipsilaterale pregressa associata a punteggio clinico Knee Society più basso (73,6±14,1 contro 80,7±12,5; p=0,036) e a un tasso di complicanza o revisione più alto ma non significativo (28,6% contro 8,1%; odds ratio 4,56; p=0,054).",concl:"Gli autori concludono che la protesi monocompartimentale mediale offre una sopravvivenza a lungo termine soddisfacente in una coorte reale, senza un'associazione chiara fra le categorie di comorbidità valutate e l'esito; la chirurgia ipsilaterale pregressa emerge come possibile segnale da usare nel colloquio preoperatorio, non come dato definitivo.",limits:"Monocentrico, un solo centro ad alto volume (Rizzoli) · la sottocoorte clinica con dati su comorbidità e chirurgia pregressa è piccola (76 ginocchia) · il segnale sulla chirurgia pregressa non raggiunge la significatività statistica (p=0,054) · marca e modello dell'impianto non specificati nell'abstract.",perte:"Diretto sulla tua pratica di protesi monocompartimentale: conferma la solidità dell'impianto a lungo termine da un centro di riferimento italiano (Zaffagnini, Grassi, Marcheggiani Muccioli — la tua rete dichiarata), e il segnale — ancora non significativo — sulla chirurgia ipsilaterale pregressa richiama da un angolo diverso il dato del registro svizzero del 15 settembre: la storia chirurgica del ginocchio operato merita di entrare nel colloquio, anche prima che uno studio lo dimostri con certezza."},{n:3,mono:"m-kssta",dot:"green",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Più slope tibiale, più cassetto anteriore residuo: il LET lo attenua",v:"319 pazienti dopo LCA con hamstring: uno slope tibiale mediale più ripido si associa a maggiore traslazione tibiale anteriore residua nel tempo (r=0,3 a 2 anni); il rinforzo laterale (LET) attenua l'effetto.",ax:"Paul, Jacquet, Ollivier",date:"set 2026",meta:"coorte retrospettiva monocentrica, 319 pazienti · [III]",pmid:'42748358',doi:'10.1002/ksa.70597',journal:"Knee Surgery, Sports Traumatology, Arthroscopy",authors:"Paul S, Ghandour M, Jacquet C, Kley K, Sammartino F, Ollivier M",design:"Coorte retrospettiva monocentrica (Marsiglia), ricostruzione primaria del LCA con autoinnesto di semitendinoso; slope tibiale posteriore mediale misurato su radiografia laterale lunga (metodo del cerchio) a 2 mesi e all'ultimo controllo; traslazione tibiale anteriore misurata con stress radiografico Telos in entrambe le ginocchia, pre-operatorio e a 2 mesi, 1 e 2 anni; regressione multivariabile con sottogruppi per età, stato cartilagineo e uso del rinforzo laterale (LET).",pop:"319 pazienti operati di ricostruzione primaria del LCA con autoinnesto di semitendinoso.",results:"Traslazione tibiale anteriore del ginocchio operato: 5,8±3,5mm preoperatoria, poi 2,9±2,3, 4,9±2,8 e 6,8±4,0mm rispettivamente a 2 mesi, 1 e 2 anni. Lo slope tibiale mediale correla positivamente ma debolmente con la differenza fra i due lati a 1 anno (r=0,2; p=0,001) e a 2 anni (r=0,3; p<0,001), ed è predittore indipendente in analisi multivariabile (p<0,01). Età più avanzata (p=0,009) e lesioni cartilaginee mediali (p=0,008) associate a maggiore lassità precoce. Il rinforzo laterale (LET) associato a una differenza fra i due lati più bassa a 2 anni (6,1 contro 7,3mm; p=0,009).",concl:"Gli autori concludono che uno slope tibiale mediale più ripido si associa a un aumento progressivo, seppure debole, della traslazione tibiale anteriore residua dopo ricostruzione del LCA, e che il rinforzo laterale extra-articolare attenua questo effetto, mentre età più avanzata e lesioni cartilaginee mediali si associano a maggiore lassità precoce.",limits:"Solo autoinnesto di semitendinoso: non verificato sul tendine quadricipitale/retto femorale che usi tu · il costrutto del rinforzo laterale (tecnica, fissazione onlay o profonda) non è descritto nell'abstract, quindi non si può dire se equivalga al tuo Lemaire modificato onlay · correlazioni deboli (r=0,2-0,3) · livello III, singolo centro.",perte:"Alimenta la tensione T1a da un angolo diretto: qui è il rinforzo laterale, non l'innesto, a ridurre la lassità residua legata allo slope — coerente con la tua indicazione universale al LET, ma su un innesto (hamstring) diverso dal tuo e con un costrutto non specificato: non risolve né la domanda sull'innesto rigido né quella sul costrutto onlay/superficiale (T1b), la rafforza soltanto sul piano del principio generale."},{n:4,mono:"m-arth",dot:"green",sec:"res",j:"Arthroscopy",h:"La guaina sinoviale del LCA predice il fallimento della riparazione",v:"281 riparazioni primarie del LCA (tecnica DiFelice, Hospital for Special Surgery): guaina sinoviale integra meno del 50% e età più giovane predicono in modo indipendente il fallimento a 2-5 anni (10% dei casi).",ax:"von Rehlingen-Prinz, Conner-Rilk, DiFelice",date:"set 2026",meta:"coorte retrospettiva monocentrica, 281 pazienti · [III]",pmid:'42748192',doi:'10.1002/arj.70554',journal:"Arthroscopy",authors:"von Rehlingen-Prinz F, Conner-Rilk S, van der List JP, Mueller MM, Wimberly A, Goodhart GC, DiFelice GS",design:"Analisi retrospettiva monocentrica (Hospital for Special Surgery, New York) di tutti i pazienti con rottura completa del LCA di tipo Sherman modificato I o II sottoposti a riparazione primaria selettiva anatomica con ancora a doppia sutura, da un singolo chirurgo (Gregory S. DiFelice), 2008-2021; grading in cieco su immagini artroscopiche di integrità della guaina sinoviale (I intatta, II >50% intatta, III <50% intatta), sede e pattern di rottura; regressione logistica uni e multivariata.",pop:"281 pazienti (50,7% donne; età media 39,1±10 anni) sottoposti a riparazione primaria del LCA; 234 (92%) con follow-up minimo 2 anni inclusi nell'analisi degli esiti.",results:"24 fallimenti su 234 (10%). All'analisi multivariata, integrità della guaina sinoviale inferiore al 50% (odds ratio 3,31; p=0,049) ed età più giovane (rischio di fallimento aumentato del 6% per ogni anno in meno; p<0,001) predittori indipendenti di fallimento. Correlazione significativa fra integrità sinoviale più bassa e pattern di rottura più complesso (p<0,001). Pattern di rottura complessi associati a esiti riferiti dal paziente peggiori a 2 anni. Affidabilità interosservatore buona-eccellente (kappa 0,734-0,956).",concl:"Gli autori concludono che una ridotta integrità della guaina sinoviale (meno del 50%) e un'età più giovane sono predittori indipendenti di fallimento dopo riparazione primaria del LCA, e che una minore integrità sinoviale si associa a pattern di rottura più complessi e a esiti peggiori.",limits:"Livello III, retrospettivo, singolo chirurgo e singolo centro · selezione rigorosa dei candidati alla riparazione (lesioni prossimali, tessuto di buona qualità): non generalizzabile a tutte le rotture del LCA · tempo medio all'ultimo esame clinico riportato di soli 3,4 mesi, più corto del follow-up dichiarato per gli esiti.",perte:"Tecnica che non esegui — operi ricostruzione, non riparazione primaria — ma è il lavoro più recente del gruppo di riferimento mondiale per questa tecnica (Gregory DiFelice, HSS), già nella tua rete di sorveglianza per la sua posizione sulla riparazione primaria del LCA: utile per il colloquio quando un paziente ti chiede conto di questa alternativa, con un tasso di fallimento del 10% guidato da un fattore anatomico intraoperatorio e dall'età."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Cartilage",h:"Il punto di riferimento sull'osteotomia cambia la deformità misurata",v:"20 pazienti operati di osteotomia tibiale alta: misurare l'asse dal punto di carico laterale invece che dal centro del ginocchio sposta tutti i parametri di allineamento e riclassifica la deformità in un caso su tre.",ax:"Fuller, Spaans, Custers",date:"set 2026",meta:"studio radiografico retrospettivo, 20 pazienti · [IV]",pmid:'42746675',doi:'10.1177/19476035261489417',journal:"Cartilage",authors:"Fuller CB, Spaans AJ, Custers RJH, Nijhuis WH, van Egmond N, Sakkers RJB, Bax EA",design:"Studio radiografico retrospettivo (Utrecht) su 20 pazienti con artrosi monocompartimentale mediale sottoposti a osteotomia tibiale alta valgizzante; confronto fra due metodi di analisi dell'allineamento dell'arto: il centro anatomico del ginocchio (tradizionale) e un punto di carico laterale al 62,5% (target chirurgico dichiarato per la sovracorrezione in valgo); confronto con test t appaiati su quattro parametri angolari.",pop:"20 pazienti con artrosi monocompartimentale mediale del ginocchio candidati a osteotomia tibiale alta.",results:"Rispetto alla misura centrata sul ginocchio, il punto di carico laterale aumenta l'angolo laterale distale femorale meccanico (mLDFA) di 1,52° (più varo), riduce l'angolo mediale prossimale tibiale meccanico (mMPTA) di 1,84° (più varo) e riduce l'angolo laterale distale tibiale meccanico (mLDTA) di 1,85° (più valgo) — tutti p<0,001. La classificazione della deformità cambia: i femori classificati in varo passano da 4 a 10 su 20, le tibie da 8 a 13 su 20.",concl:"Gli autori concludono che l'uso di un punto di carico laterale per l'analisi della deformità produce cambiamenti prevedibili nei parametri di allineamento che spesso ne cambiano la classificazione, potenzialmente rivelando deformità femorali sottostimate dal metodo tradizionale centrato sul ginocchio.",limits:"20 pazienti, studio radiografico retrospettivo di un solo centro · nessun esito clinico riportato: dimostra un effetto sulla misura, non ancora un impatto su pianificazione o risultato chirurgico · confronto solo fra due metodi, non validato contro un riferimento TC 3D.",perte:"Diretto sulla tua pratica di osteotomie correttive, incluse quelle di slope: il punto di riferimento scelto per l'analisi radiografica preoperatoria cambia la classificazione della deformità in una minoranza rilevante di casi (fino a un terzo per il femore) — un argomento per rivedere quale punto di riferimento usi in fase di pianificazione, prima ancora del calcolo dell'angolo di correzione."},{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"The American Journal of Sports Medicine",h:"Nell'osteocondrite dissecante il fascio del LCA è più orizzontale",v:"90 ginocchia in tre coorti pediatriche appaiate: nell'osteocondrite dissecante del condilo femorale laterale il fascio postero-laterale del LCA si inserisce più in basso e più orizzontale che nei controlli.",ax:"Lehoczky, Khoo, Shea",date:"set 2026",meta:"studio caso-controllo, 90 ginocchia/90 pazienti · [III]",pmid:'42745400',doi:'10.1177/03635465261479922',journal:"The American Journal of Sports Medicine",authors:"Lehoczky G, Khoo B, Lin Z, Shea KG",design:"Studio caso-controllo retrospettivo su risonanza magnetica, tre coorti abbinate per età e sesso (rapporto 1:1:1): osteocondrite dissecante (OCD) del condilo femorale laterale, OCD del condilo femorale mediale come controllo di patologia, ginocchia senza patologia strutturale come controllo sano; misura dell'altezza di inserzione del fascio postero-laterale del LCA relativa all'altezza della fisi e del condilo femorale laterale sul piano coronale; angolo femoro-tibiale calcolato per verificare la coerenza del piano di misura. Pazienti <18 anni, LCA integro, esclusi i menischi discoidi.",pop:"90 ginocchia in 90 pazienti, età media 12,5 anni (range 8-16), 67% maschi; 30 ginocchia per ciascuna delle tre coorti.",results:"Altezza di inserzione del fascio postero-laterale significativamente diversa fra i gruppi sia rispetto all'altezza della fisi sia rispetto all'altezza del condilo femorale laterale (p<0,001 per entrambe le misure). Nel gruppo con OCD del condilo laterale, l'inserzione è la più bassa: 0,36±0,06 relativa al condilo e 0,46±0,07 relativa alla fisi, contro 0,43±0,09/0,50±0,11 nell'OCD mediale e 0,43±0,08/0,55±0,11 nei controlli sani.",concl:"Gli autori concludono che esiste un'associazione fra una posizione più orizzontale, o un punto di inserzione femorale più distale, del fascio postero-laterale del LCA e l'osteocondrite dissecante del condilo femorale laterale, ipotizzando un possibile ruolo futuro come fattore predittivo di guarigione, da studiare ulteriormente.",limits:"Studio caso-controllo retrospettivo, livello III: associazione anatomica, non causalità dimostrata · popolazione in parte sotto i 14 anni (età media 12,5, range 8-16), sotto la soglia della tua pratica abituale · nessun LCA operato in questa coorte: non riguarda una ricostruzione.",perte:"Fuori dalla tua pratica diretta — qui il LCA è integro e la popolazione è in gran parte pediatrica, sotto i 14 anni che operi — ma rilevante per la comprensione anatomica dell'inserzione del fascio postero-laterale in generale e per il sospetto diagnostico quando incontri un'osteocondrite dissecante del condilo laterale in un adolescente al limite della tua fascia d'età."}];
var SUGGQ=[{"k": "kol", "n": "Matthieu Ollivier", "w": "Institute for Locomotion, Sainte-Marguerite Hospital, Aix-Marseille University, AP-HM, Marsiglia, Francia", "r": "Autore senior dello studio di oggi su slope tibiale, traslazione anteriore residua e rinforzo laterale dopo LCA (scheda 3): già coautore ricorrente su slope/osteotomia (tensione T1a del 27 agosto). Corrispondenza tecnica diretta con T1a e T2b. Sostituisce la proposta invariata di Brian J. Cole (16 settembre)."}];
var BRIEF_TEXT="Oggi sei lavori. Il più rilevante è un consenso formale internazionale — 106 esperti di ESSKA/EKA insieme a EHS e APAS — che per la prima volta mette per iscritto 63 raccomandazioni condivise sui percorsi di recupero rapido (fast-track/ERAS) in protesi di anca e di ginocchio: 39 basate su evidenza solida, le altre 24 su opinione di esperti con un accordo comunque molto alto. Dal Rizzoli di Bologna arriva la sopravvivenza a lungo termine di 168 protesi monocompartimentali mediali — fino al 78% a 15 anni — con un segnale, ancora non significativo, che la chirurgia già subita sullo stesso ginocchio pesa sul risultato: un tema che si aggiunge a quanto emerso il 15 settembre dal registro svizzero. Da Marsiglia, uno studio su 319 pazienti operati di legamento crociato con hamstring mostra che il rinforzo laterale attenua l'aumento di lassità residua legato a uno slope tibiale più ripido — un segnale in più a favore della tua indicazione universale al rinforzo, anche se non sul tuo innesto né sul tuo costrutto. Dal gruppo di riferimento mondiale per la riparazione primaria del crociato (Gregory DiFelice, Hospital for Special Surgery) arriva il dato più ampio finora sui suoi fallimenti: un caso su dieci, guidato dall'integrità della guaina sinoviale e dall'età. Uno studio olandese mostra quanto conti, nella pianificazione di un'osteotomia, il punto di riferimento scelto per misurare la deformità della gamba. Chiude la giornata un lavoro pediatrico su un possibile legame anatomico fra l'osteocondrite dissecante del condilo laterale e la posizione del fascio postero-laterale del legamento crociato, fuori dalla tua pratica diretta ma utile per l'anatomia. Nessun richiamo di dispositivo oggi; confermata, invariata, l'unica segnalazione nota dal 3 settembre (Expression of Concern su un lavoro estraneo a queste pagine). Il raccoglitore notturno non ha depositato nulla di nuovo da due notti: i richiami, i trial e le ritrattazioni di oggi vengono dalla verifica diretta su PubMed, non dal deposito automatico.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi partiamo da un evento raro: un consenso formale internazionale sul recupero rapido dopo protesi di anca e ginocchio."}, {"chi": "B", "t": "Chi l'ha scritto?"}, {"chi": "A", "t": "Centosei esperti, ESSKA ed EKA insieme a EHS e APAS. Sessantatré raccomandazioni, quasi due terzi basate su evidenza solida."}, {"chi": "B", "t": "Quindi cambia il modo di operare?"}, {"chi": "A", "t": "No, cambia tutto quello che sta intorno — preparazione, sala operatoria, dimissione. Per la tua pratica quotidiana di protesi di ginocchio è un metro di paragone nuovo per il protocollo."}, {"chi": "B", "t": "E il resto della giornata?"}, {"chi": "A", "t": "Dal Rizzoli arriva la sopravvivenza di 168 protesi parziali fino a quindici anni: numeri molto solidi, e un segnale — non ancora significativo — che la chirurgia già fatta sullo stesso ginocchio pesa sul risultato."}, {"chi": "B", "t": "Come il registro svizzero del 15 settembre."}, {"chi": "A", "t": "Esatto, stesso tema da un angolo diverso. Poi da Marsiglia: il rinforzo laterale riduce la lassità residua legata a uno slope tibiale più ripido — ma è uno studio su hamstring, non sul tuo innesto."}, {"chi": "B", "t": "E la riparazione primaria del crociato?"}, {"chi": "A", "t": "Il gruppo di DiFelice pubblica il dato più ampio finora: un fallimento su dieci, legato all'integrità della guaina sinoviale e all'età. Tecnica che non usi, ma utile per il colloquio."}, {"chi": "B", "t": "Quindi per la tua pratica quotidiana, cosa resta da fare oggi?"}, {"chi": "A", "t": "Guardare come pianifichi le osteotomie: uno studio olandese mostra che il punto di riferimento usato per misurare la deformità cambia la classificazione in un caso su tre. Vale la pena rivederlo."}];
